["Hooks"] = {
["Cast Update"] = "function (self, unitId, unitFrame, envTable, modTable)\n    envTable.EnhancedCastBar(unitId, unitFrame.castBar)\nend\n\n\n",
["Cast Stop"] = "function (self, unitId, unitFrame, envTable, modTable)\n    if unitFrame.castBar.tick then\n        unitFrame.castBar.tick:Hide()\n    end\nend",
["Cast Start"] = "function (self, unitId, unitFrame, envTable, modTable)\n    -- Flashing nameplate options\n    envTable.optionsHideFlashSolo = modTable.config.hideNameplateFlashSolo\n    envTable.optionsNameplateFlash = modTable.config.nameplateFlash\n    envTable.optionsHideFlashAsTank = modTable.config.hideFlashAsTank\n    \n    -- Target name options\n    envTable.optionsShowTargetName = modTable.config.showTargetName\n    envTable.optionsReplaceMyName = modTable.config.replaceName\n    envTable.optionsHideNameSolo = modTable.config.hideNameSolo\n    envTable.optionsCastNameSize = modTable.config.castNameSize\n    \n    -- Cast bar interrupt coloring\n    envTable.optionsShowInterruptColor = modTable.config.showInterruptColor\n    envTable.optionsShowSecondaryInterrupts = modTable.config.showSecondaryInterrupts\n    envTable.optionsColorNoInterrupt = modTable.config.colorNoInterrupt\n    envTable.optionsColorInterruptAvailable = modTable.config.colorInterruptAvailable\n    envTable.optionsColorInterruptSoon = modTable.config.colorInterruptSoon\n    envTable.optionsColorSecondaryAvailable = modTable.config.colorSecondaryInterrupt\n    envTable.optionsColorProtected = modTable.config.colorProtected\n    envTable.optionsColorTick = modTable.config.colorTick\n    \n    envTable.interruptID = envTable.GetInterruptId()\n    \n    envTable.EnhancedCastBar(unitId, unitFrame.castBar)\nend",
["Initialization"] = "function(modTable)\n    modTable.reflectableSpells = {}\n    \n    if select(3, UnitClass(\"player\")) == 1 then\n        \n        \n        --TWW Dungeons \n        local araKara = {\n            438200, -- Poison bolt\n            436322, -- Poison bolt - atik\n            434786, -- Web bolt\n        }\n        \n        local cityOfThreads = {\n            434722, -- Subjugate - Orator Krix\n            442536, -- Grimweave Blast\n            443427, -- Web Bolt\n        }\n        \n        local theDawnbreaker = {\n            428086, -- Shadow bolt\n            451114, -- Congealed Shadow\n            431333, -- Tormenting Beam\n            431495, -- Black Edge\n            451113, -- Web Bolt\n        }\n        \n        local theStonevault = {\n            429422, -- Stone Bolt\n            426283, -- Arcing Void\n            429110, --Alloy Bolt\n            429545, -- Censoring Gear\n            459210, -- Shadow Claw\n        }\n        \n        local cinderbrewMeadery = {\n            \n        }\n        \n        local darkflameCleft = { \n            \n        }\n        \n        local prioryOfTheSacredFlame = {\n            \n        }\n        \n        local theRookery = {\n            \n        }\n        \n        \n        \n        --DF Dungeons\n        \n        local murozondsRise = {\n            400165, -- Epoch Bolt\n            413607, -- Corroding Volley\n            418202, -- Temporal Blast\n            417030, -- Fireball\n            411763, -- Infinite Blast\n            407121, -- Immolate\n        }\n        \n        local galakrondsFall = {\n            415435, -- Infinite Bolt\n            413590, -- Noxious Ejection\n            411958, -- Stonebolt\n        }\n        \n        local rubyLifePools = {\n            373803, -- Cold Claws boss adds\n            372683, -- Cold Claws trash\n            372808, -- Frigid Shard\n            373693, -- Living Bomb\n            371984, -- Icebolt\n            384197, -- Cinderbolt\n            384194, -- Cinderbolt\n            392576, -- Thunderbolt\n            385310, -- Lightning Bolt\n            385536, -- Flame Dance\n        }\n        \n        local azureVault = {\n            374789, -- Infused Strike\n            373932, -- Illusionary Bolt\n            384978, -- Dragon Strike\n            377503, -- Condensed Frost\n            389804, -- Heavy Tome\n            371306, -- Arcane Bolt\n        }\n        \n        local brackenhideHollow = {\n            382249, -- Earth Bolt\n            381694, -- Decayed Senses\n            378155, -- Earth Bolt (boss)\n            382474, -- Decay Surge\n        }\n        \n        local hallsOfInfusion = {\n            374020, -- Containment Beam\n            389443, -- Purifying Blast\n            374706, -- Pyretic Burst\n            375950, -- Ice Shard\n            385963, -- Frost Shock\n            395690, -- Lightning Blast\n            387504, -- Squall Buffet\n            387571, -- Focused Deluge\n        }\n        \n        local uldaman = {\n            369674, -- Stone Spike\n            369675, -- Chain Lightning\n            372718, -- Earthen Shards\n            369399, -- Stone Bolt\n            369365, -- Curse of Stone\n            377395, -- Time Sink\n        }\n        \n        local neltharus = {\n            378818, -- Magma Conflagration\n            372538, -- Melt\n            383231, -- Lava Bolt\n        }\n        \n        local nokhudOffensive = {\n            387125, -- Thunderstrike\n            387127, -- Chain Lightning\n            386012, -- Stormbolt\n            387613, -- Death Bolt\n            382670, -- Gale Arrow\n            376827, -- Conductive Strike\n            384761, -- Wind Burst\n            396206, -- Storm Shock\n            381530, -- Storm Shock\n        }\n        \n        local algetharAcademy = {\n            388862, -- Surge\n            377991, -- Storm Slash\n            387975, -- Arcane Missiles\n        }\n        \n        --Shadowlands Dungeons\n        \n        local mistsOfTirnaScithe = {\n            332767, --Spirit Bolt\n            323057, --Spirit Bolt - Boss\n            332557, --Soul Split\n            463217, --Anima Slash\n            325223, --Anima Injection\n            332486, --Overgrowth\n            \n        }\n        \n        local theNecroticWake = {\n            328667, --Frostbolt Volley\n            326574, --Noxious Fog\n            320788, --Frozen Binds\n            322274, --Enfeeble\n            334748, --Drain Fluids\n            320462, --Necrotic Bolt\n            333479, --Spew Disease\n            323347, --Clinging Darkness\n        }\n        \n        \n        \n        --BFA Dungeons\n        \n        local siegeOfBoralus = {\n            272581, -- Water bolt\n            257063, -- Brackish bolt\n        }\n        \n        local waycrestManor = {\n            265372, -- Shadow Cleave\n            263943, -- Etch\n            264105, -- Runic Mark\n            260701, -- Bramble Bolt\n            260699, -- Soul Bolt\n            260700, -- Ruinous Bolt\n            266036, -- Drain Essence\n            264024, -- Soul Bolt\n            426541, -- Runic Bolt\n            264556, -- Tearing Strike\n            264153, -- Spit\n            278444, -- Infest\n            265881, -- Decaying Touch\n            265880, -- Dread Mark\n            268278, -- Wracking Chord\n            261438, -- Wasting Strike\n            261440, -- Virulent Pathogen\n        }\n        \n        local atalDazar = {\n            253562, -- Wildfire\n            254959, -- Soul Burn\n            252923, -- Venom Blast\n            252687, -- Venomfang Strike\n            250096, -- Wracking Pain\n        }\n        \n        local underrot = {\n            265084, -- Blood Bolt\n            260879, -- Blood Bolt (boss)\n            278961, -- Decaying Mind\n            266265, -- Wicked Embrace\n            272180, -- Void Spit\n        }\n        \n        local freehold = {\n            259092, -- Lightning Bolt\n            257908, -- Oiled Blade\n            281420, -- Water Bolt\n        }\n        \n        \n        --Legion Dungeons\n        \n        local darkheartThicket = {\n            204243, -- Tormenting Eye\n            200238, -- Feed on the Weak\n            200185, -- Nightmare Bolt\n            200684, -- Nightmare Toxin\n            200642, -- Despair\n            201411, -- Firebolt\n            201837, -- Shadow Bolt\n        }\n        \n        local blackRookHold = {\n            199663, -- Soul Blast\n            200248, -- Arcane Blitz\n        }\n        \n        local neltharionsLair = {\n            186269, -- Stone Bolt\n            198496, -- Sunder\n            210150, -- Toxic Retch\n            200732, -- Molten Crash\n        }\n        \n        local hallsOfValor = {\n            198595, -- Thunderous Bolt\n            198962, -- Shattered Rune\n            198959, -- Etch\n            191976, -- Arcing Bolt\n            192288, -- Searing Light\n        }\n        \n        local courtOfStars = {\n            209036, -- Throw Torch\n            209413, -- Suppress\n            211406, -- Firebolt\n            211473, -- Shadow Slash\n            373364, -- Vampiric Claws\n        }\n        \n        \n        --WoD Dungeons\n        \n        local everbloom = {\n            169657, -- Poisonous Claws\n            168040, -- Nature's Wrath\n            168092, -- Water Bolt\n            169840, -- Frostbolt\n            169841, -- Arcane Blast\n            169839, -- Pyroblast\n            427858, -- Fireball\n            164965, -- Choking Vines\n        }\n        \n        local shadowmoonBurialGrounds = {\n            152814, -- Shadow Bolt\n            152819, -- Shadow Word: Frailty\n            156776, -- Rending Voidlash\n            398206, -- Death Blast\n            153067, -- Void Devastation\n            153524, -- Plague Spit\n        }\n        \n        --MoP Dungeons\n        \n        local templeOfTheJadeSerpent = {\n            397888, -- Hydrolance\n            114803, -- Throw Torch\n            114571, -- Agony\n            397914, -- Defiling Mist\n            397931, -- Dark Claw\n            106823, -- Serpent Strike\n        }\n        \n        \n        --Cata Dungeons\n        \n        local throneOfTheTides = {\n            426731, -- Water Bolt\n            428542, -- Crushing Depths\n            426768, -- Lightning Bolt\n            75992, -- Lightning Surge\n            428374, -- Focused Tempest\n            426783, -- Mind Flay\n            429048, -- Flame Shock\n            429173, -- Mind Rot\n            429176, -- Aquablast\n            428526, -- Ink Blast\n            428889, -- Foul Bolt\n        }\n        \n        local vortexPinnacle = {\n            410873, -- Rushing Wind\n            86331, -- Lightning Bolt\n            411019, -- Starlight\n            87762, -- Lightning Lash\n            87622, -- Chain Lightning\n        }\n        \n        local grimBatol = { \n            447966, --Shadowflame bolt\n            450087, --Depth's Grasp\n            451971, --Lava Fist\n        }\n        \n        \n        \n        -- Raids\n        local amidrassil = {\n            431302, -- Fyr'alath's Flame, Fyrakk\n            421284, -- Coiling Flames, Volcoross\n        }\n        \n        local aberrus = {\n            403203, -- Flame Slash, Amalgamation Chamber\n            403699, -- Shadow Spike\n            397386, -- Lava Bolt, trash\n            410351, -- Flaming Cudgel, Assault\n        }\n        \n        local vault = {\n            396040, -- Pyroblast, Eranog\n            372394, -- Lightning Bolt, Council\n            372315, -- Frost Spike\n            372275, -- Chain Lightning\n            385812, -- Aerial Slash, Dathea\n            375716, -- Ice Barrage, Diurna\n            385553, -- Storm Bolt\n            375653, -- Static Jolt\n        }\n        \n        local zones = {\n            araKara,\n            cityOfThreads,\n            grimBatol,\n            mistsOfTirnaScithe,\n            siegeOfBoralus,\n            theDawnbreaker,\n            theNecroticWake,\n            theStonevault,\n            cinderbrewMeadery,\n            darkflameCleft,\n            prioryOfTheSacredFlame,\n            theRookery,\n            rubyLifePools,\n            azureVault,\n            brackenhideHollow,\n            uldaman,\n            neltharus,\n            algetharAcademy,\n            nokhudOffensive,\n            hallsOfInfusion,\n            darkheartThicket,\n            everbloom,\n            throneOfTheTides,\n            waycrestManor,\n            atalDazar,\n            blackRookHold,\n            vortexPinnacle,\n            underrot,\n            freehold,\n            neltharionsLair,\n            templeOfTheJadeSerpent,\n            courtOfStars,\n            shadowmoonBurialGrounds,\n            hallsOfValor,\n            murozondsRise,\n            galakrondsFall,\n            amidrassil,\n            aberrus,\n            vault,\n        }\n        \n        for i = 1, #zones do\n            local zone = zones[i]\n            \n            for k = 1, #zone do\n                local id = zone[k]\n                modTable.reflectableSpells[id] = true\n            end\n        end\n    end\nend",
["Constructor"] = "function (self, unitId, unitFrame, envTable, modTable)\n    -- Create a tick if it doesn't already exist. The tick will be used to show when interrupt will be available.\n    if not unitFrame.castBar.tick then\n        unitFrame.castBar.tick = unitFrame.castBar:CreateTexture(nil, \"overlay\")\n        unitFrame.castBar.tick:SetDrawLayer(\"overlay\", 4)\n        unitFrame.castBar.tick:SetBlendMode(\"DISABLE\")\n        --unitFrame.castBar.tick:SetHeight(unitFrame.castBar:GetHeight())\n        unitFrame.castBar.tick:SetHeight(8)\n    end\n    unitFrame.castBar.tick:SetTexture(Plater.SparkTextures[8])\n    unitFrame.castBar.tick:SetVertexColor(Plater:ParseColors(envTable.optionsColorTick))\n    unitFrame.castBar.tick:SetWidth(2)\n    \n    ---@param spellId number\n    ---@return number, number, number, number\n    function envTable.GetSpellCooldown(spellId)\n        if C_Spell.GetSpellCooldown then\n            local info = C_Spell.GetSpellCooldown(spellId)\n            return info.startTime, info.duration, info.isEnabled, info.modRate\n        end\n        \n        return GetSpellCooldown(spellId)\n    end\n    \n    ---@param unitId string\n    function envTable.EnhancedCastBar(unitId, castBar)\n        castBar.tick:Hide()\n        \n        if castBar.IsInterrupted then\n            return\n        end\n        \n        local targetUnitId = unitId .. \"target\"\n        \n        if not UnitExists(targetUnitId) then\n            return\n        end\n        \n        local targetName = UnitName(targetUnitId)\n        local spellName = castBar.SpellName\n        local inParty = UnitInParty(\"player\")\n        local inRaid = UnitInRaid(\"player\")\n        castBar.Text:SetText(spellName)\n        local isTargettingMe = targetName == UnitName(\"player\")\n        \n        -- Cast is targetting a specific unit\n        if targetName then\n            -- Nameplate flash options\n            if isTargettingMe then\n                if envTable.optionsNameplateFlash then\n                    -- Default value of true since it is turned on in the options\n                    local showNameplateFlash = true\n                    \n                    -- Hide flash when not in a group\n                    if envTable.optionsHideFlashSolo then\n                        if not inParty and not inRaid then\n                            showNameplateFlash = false\n                        end\n                    end\n                    \n                    -- Hide flash when player is a tank specialization\n                    if envTable.optionsHideFlashAsTank then\n                        if GetSpecializationRole(GetSpecialization()) == \"TANK\" then\n                            showNameplateFlash = false\n                        end\n                    end\n                    \n                    -- Show nameplate flash if conditions met\n                    if showNameplateFlash then\n                        Plater.FlashNameplateBody(unitFrame)\n                    end\n                end\n            end\n            \n            -- Target name in cast bar options\n            if envTable.optionsShowTargetName then\n                -- Change character name to \"Me\" if turned on in options\n                if envTable.optionsReplaceMyName and isTargettingMe then\n                    targetName = \"Me\"\n                end\n                \n                -- Color the target name based on the targets class color\n                local targetNameByColor = Plater.SetTextColorByClass(targetUnitId, targetName)\n                \n                -- Shrink the name of the cast bar text if necessary (based on options)\n                local castBarWidth = castBar:GetWidth()\n                DetailsFramework:TruncateText(castBar.Text, castBarWidth * (envTable.optionsCastNameSize / 100))\n                \n                -- Update the cast bar text\n                local currentText = castBar.Text:GetText()\n                if currentText ~= nil and currentText ~= \"\" then\n                    local castText = currentText .. \" \" .. targetNameByColor\n                    \n                    -- Hide self target name when solo\n                    if envTable.optionsHideNameSolo then\n                        if not inParty and not inRaid then\n                            if isTargettingMe then\n                                castText = currentText\n                            end\n                        end\n                    end\n                    castBar.Text:SetText(castText)\n                    DetailsFramework:TruncateText(castBar.Text, castBarWidth)\n                end\n            end\n        end\n        \n        if not envTable.optionsShowInterruptColor then\n            return\n        end\n        \n        -- Interrupt bar color options\n        local canInterrupt = castBar.canInterrupt\n        local castEndTime = castBar.spellEndTime\n        local interruptReadyTime = 0\n        local start\n        local duration\n        \n        if envTable.interruptID ~= nil then\n            start, duration = envTable.GetSpellCooldown(envTable.interruptID) --local\n            interruptReadyTime = start + duration\n        end\n        \n        if canInterrupt then\n            if envTable.interruptID ~= nil then\n                -- Is the player a warlock?\n                local playerIsWarlock = envTable.class == 9\n                \n                -- Check to see if the spell is known/talented\n                if IsSpellKnown(envTable.interruptID, playerIsWarlock) then\n                    if interruptReadyTime == 0 then\n                        Plater.SetCastBarColor(unitFrame, envTable.optionsColorInterruptAvailable)\n                    elseif\n                    envTable.optionsShowSecondaryInterrupts\n                    and envTable.class == 2 -- paladin\n                    and IsSpellKnown(31935) -- avenger's shield\n                    and not envTable.isSpellOnCooldown_IgnoreGCD(31935)\n                    then\n                        -- Paladin Avenger's Shield\n                        Plater.SetCastBarColor(unitFrame, envTable.optionsColorSecondaryAvailable)\n                    elseif interruptReadyTime < (castEndTime - 0.25) then\n                        castBar.tick:Show()\n                        castBar.tick:SetVertexColor(Plater:ParseColors(envTable.optionsColorTick))\n                        local tickLocation = (start + duration - castBar.spellStartTime) / castBar.maxValue -- castBar.spellStartTime + 0.25\n                        if castBar.channeling then\n                            tickLocation = 1 - tickLocation\n                        end\n                        castBar.tick:SetPoint(\"center\", castBar, \"left\", tickLocation * castBar:GetWidth(), 0)\n                        \n                        Plater.SetCastBarColor(unitFrame, envTable.optionsColorInterruptSoon)\n                    elseif interruptReadyTime >= (castEndTime - 0.25) then\n                        Plater.SetCastBarColor(unitFrame, envTable.optionsColorNoInterrupt)\n                    end\n                else\n                    Plater.SetCastBarColor(unitFrame, envTable.optionsColorNoInterrupt)\n                end\n            end\n        else\n            Plater.SetCastBarColor(unitFrame, envTable.optionsColorProtected)\n        end\n        \n        -- Spell Reflection coloring\n        if\n        envTable.optionsShowSecondaryInterrupts\n        and isTargettingMe\n        and envTable.class == 1\n        and IsSpellKnown(23920) -- spell reflect\n        and not envTable.isSpellOnCooldown_IgnoreGCD(23920)\n        and modTable.reflectableSpells[castBar.SpellID] == true\n        then\n            -- Color the bar if the spell is reflectable\n            Plater.SetCastBarColor(unitFrame, envTable.optionsColorSecondaryAvailable)\n        end\n    end\n    \n    envTable.class = select(3, UnitClass(\"player\"))\n    \n    local function determineInterruptId()\n        if envTable.class == 1 then -- Warrior\n            return function()\n                return 6552 -- Pummel\n            end\n        end\n        \n        if envTable.class == 2 then -- Paladin\n            return function()\n                return 96231 -- Rebuke\n            end\n        end\n        \n        if envTable.class == 3 then -- Hunter\n            return function()\n                local spec = GetSpecialization()\n                \n                if spec == 3 then -- survival\n                    return 187707 -- muzzle\n                end\n                \n                return 147362 -- counter shot\n            end\n        end\n        \n        if envTable.class == 4 then -- rogue\n            return function()\n                return 1766 -- kick\n            end\n        end\n        \n        if envTable.class == 5 then -- priest\n            return function()\n                local spec = GetSpecialization()\n                \n                if spec == 3 then -- shadow\n                    return 15487 -- silence\n                end\n                \n                return nil\n            end\n        end\n        \n        if envTable.class == 6 then -- death knight\n            return function()\n                return 47528 -- mind freeze\n            end\n        end\n        \n        if envTable.class == 7 then -- shaman\n            return function()\n                return 57994\n            end\n        end\n        \n        if envTable.class == 8 then -- mage\n            return function()\n                return 2139 -- counterspell\n            end\n        end\n        \n        if envTable.class == 9 then -- warlock\n            return function()\n                if IsSpellKnown(89766, true) then -- felguard: axe toss\n                    return 89766\n                end\n                \n                if IsSpellKnown(19647, true) then -- felhunter: spell lock\n                    return 19647\n                end\n                \n                if C_UnitAuras.GetPlayerAuraBySpellID(196099) ~= nil and IsSpellKnown(132409, true) then -- spell lock via grimoire of sacrifice\n                    return 132409\n                end\n                \n                return nil\n            end\n        end\n        \n        if envTable.class == 10 then -- monk\n            return function()\n                return 116705 -- spear hand strike\n            end\n        end\n        \n        if envTable.class == 11 then -- druid\n            return function()\n                local spec = GetSpecialization()\n                \n                if spec == 1 then -- balance\n                    return 78675 -- soalr beam\n                end\n                \n                return 106839 -- skull bash\n            end\n        end\n        \n        if envTable.class == 12 then -- demon hunter\n            return function()\n                return 183752 -- disrupt\n            end\n        end\n        \n        if envTable.class == 13 then -- evoker\n            return function()\n                return 351338 -- quell\n            end\n        end\n    end\n    \n    envTable.GetInterruptId = determineInterruptId()\n    \n    -- Checks to see if a spell is on cooldown, not counting the 1.5s cooldown from global cooldown.\n    ---@param spellID number\n    ---@return boolean\n    function envTable.isSpellOnCooldown_IgnoreGCD(spellID)\n        local gcdSTART, gcdDUR = envTable.GetSpellCooldown(61304) -- GCD\n        local GCD_expirationTime = gcdSTART + gcdDUR\n        local spellStart, spellDuration = envTable.GetSpellCooldown(spellID)\n        local spellReadyTime = spellStart + spellDuration\n        return spellReadyTime > GCD_expirationTime\n    end\nend",
},
