["Hooks"] = {
["Initialization"] = "function(modTable)\n    local default = \"#00fbff\"\n    \n    modTable.NpcColors = {\n        -- Vault of the Incarnates [VOTI]\n        [191222] = default, -- Juvenile Frost Proto-Dragon\n        [199547] = default, -- Frostforged Zealot\n        -- Ruby Life Pools [RLP]\n        [187897] = default, -- Defier Draghar\n        [188244] = default, -- Primal Juggernaut\n        [195119] = default, -- Primalist Shockcaster\n        [197698] = default, -- Thunderhead\n        [198047] = default, -- Tempest Channeler\n        [197535] = default, -- High Channeler Ryvati\n        -- Algeth’ar Academy [AA]\n        [196576] = default, -- Spellbound Scepter\n        [196671] = default, -- Arcane Ravager\n        [197219] = default, -- Vile Lasher\n        [196203] = default, -- Ethereal Restorer\n        [192680] = default, -- Guardian Sentry\n        [192333] = default, -- Alpha Eagle\n        -- Nokhud Offensive [NO]\n        [192800] = default, -- Nokhud Lancemaster\n        [195696] = default, -- Primalist Thunderbeast\n        [194897] = default, -- Stormsurge Totem\n        [195927] = default, -- Soulharvester Galtmaa\n        [195928] = default, -- Soulharvester Duuren\n        [195930] = default, -- Soulharvester Mandakh\n        [195929] = default, -- Soulharvester Tumen\n        [193462] = default, -- Batak\n        -- Azure Vault [AV]\n        [187159] = default, -- Shrieking Whelp\n        [187155] = default, -- Rune Seal Keeper\n        [196116] = default, -- Crystal Fury\n        [191739] = default, -- Scalebane Lieutenant\n        [187240] = default, -- Drakonid Breaker\n        -- Court of Stars [COS]\n        [104251] = default, -- Duskwatch Sentry\n        [105715] = default, -- Watchful Inquisitor\n        [104278] = default, -- Felbound Enforcer\n        [105704] = default, -- Arcane Manifestation\n        -- Halls of Valor [HOV]\n        [97068] = default, -- Storm Drake\n        [95834] = default, -- Valarjar Mystic\n        [96574] = default, -- Stormforged Sentinel\n        -- Shadowmoon Burial Grounds [SBG]\n        [75713] = default, -- Shadowmoon Bone-Mender\n        [75652] = default, -- Void Spawn\n        [75979] = default, -- Exhumed Spirit\n        -- Temple of the Jade Serpent [TJS]\n        [200126] = default, -- Fallen Waterspeaker\n        [59546] = default, -- The Talking Fish\n        [59553] = default, -- The Songbird Queen\n        [59545] = default, -- The Golden Beetle\n        [59555] = default, -- Haunting Sha\n    }\n    \n    function modTable.UpdateColor(unitFrame, envTable)\n        if not unitFrame or unitFrame.IsNpcWithoutHealthbar or unitFrame.IsFriendlyPlayerWithoutHealthbar then return end\n        -- Get color from modTable.NpcColors\n        local color = modTable.NpcColors [unitFrame.namePlateNpcId]\n        -- Set color from modTable.NpcColors\n        if (color) then\n            Plater.SetNameplateColor(unitFrame, color)\n        end\n    end\nend",
