{
["ConstructorCode"] = "function (self, unitId, unitFrame, envTable, scriptTable)\n    if scriptTable.config.isFlashEnabled then\n        envTable.fsFlash = envTable.fsFlash or Plater.CreateFlash (unitFrame.healthBar, 0.5, 12, scriptTable.config.npColor)\n    end\n    \n    if scriptTable.config.isGlowEnabled then\n        self.pandemicGlow = self.pandemicGlow or Plater.CreateIconGlow (self)\n        envTable.pandemicGlow = self.pandemicGlow\n    end\n    \n    \nend    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
["OnHideCode"] = "function (self, unitId, unitFrame, envTable, scriptTable)\n    Plater.SetNameplateColor (unitFrame)\n    \n    if scriptTable.config.isFlashEnabled then\n        envTable.fsFlash:Stop()\n    end\n    \n    if scriptTable.config.isGlowEnabled then\n        envTable.pandemicGlow:Hide()\n    end\n    \n    if scriptTable.config.isTimerColorEnabled then\n        Plater:SetFontColor (self.Cooldown.Timer, Plater.db.profile.aura_timer_text_color)\n    end\n    \n    --reset the border color\n    self:SetBackdropBorderColor (0, 0, 0, 0)\n    self:SetScale(1)\nend\n\n\n\n\n\n\n\n\n\n\n\n\n",
