["Prio"] = 99,
["Name"] = "Pandemic Glow (Pixel)",
["PlaterCore"] = 1,
["version"] = -1,
["Desc"] = "Adds a configurable pixel border glow to the buff/debuff if the remaining duration is less than 30% of its total duration.",
["Options"] = {
},
